from nanobrain.core.step import BaseStep, StepConfig

class ThresholdStepConfig(StepConfig):
    threshold: float = 0.0

class ThresholdStep(BaseStep):
    _config_class = ThresholdStepConfig

    def __init__(self, config: dict):
        super().__init__(config)
        self._threshold = self.config.threshold

    async def process(self, input_data: dict, **kwargs) -> dict:
        items = input_data["items"]
        return {"above": [x for x in items if x > self._threshold]}

from nanobrain.core.step import BaseStep

class DedupePreserveOrderStep(BaseStep):
    async def process(self, input_data: dict, **kwargs) -> dict:
        items = input_data["items"]
        seen = set()
        unique_items = []
        for item in items:
            if item not in seen:
                seen.add(item)
                unique_items.append(item)
        return {"unique": unique_items}

